using namespace Halide;

/*
 * Array initialization, translated to Halide.
 *
 * Original C:
 *
 * for (i = 0; i < m; i++)
 *   p[i] = (DATA_TYPE)(i % m) / m;
 * for (i = 0; i < n; i++) {
 *   r[i] = (DATA_TYPE)(i % n) / n;
 *   for (j = 0; j < m; j++)
 *     A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
 * }
 *
 * C layout: A[N][M] accessed as A[i][j].
 * Halide layout: Buffer A(m, n) accessed as A(j, i).
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 1> r,
                       Halide::Buffer<num_t, 1> p) {
    Var i("i"), j("j");

    Func init_p("init_p"), init_r("init_r"), init_A("init_A");

    // p[i] = (i % m) / m;
    init_p(i) = cast<num_t>(i % m) / cast<int>(m);

    // r[i] = (i % n) / n;
    init_r(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = (i * (j + 1) % n) / n;
    // C index: A[i][j]  -> Halide: A(j, i)
    init_A(j, i) = cast<num_t>((i * (j + 1)) % n) / cast<int>(n);

    init_p.realize(p);
    init_r.realize(r);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Buffers:
    // C: A[N][M] -> Buffer A(m, n) with A(j, i)
    Halide::Buffer<num_t, 2> A(m, n);
    Halide::Buffer<num_t, 1> s(m);
    Halide::Buffer<num_t, 1> q(n);
    Halide::Buffer<num_t, 1> p(m);
    Halide::Buffer<num_t, 1> r(n);

    // Initialize data
    init_array(m, n, A, r, p);

    // ImageParams for inputs
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam p_param(type_of<num_t>(), 1, "p_param");
    ImageParam r_param(type_of<num_t>(), 1, "r_param");

    A_param.set(A);
    p_param.set(p);
    r_param.set(r);

    // Vars and reduction domains
    Var i("i"), j("j");

    // s[j] = sum_i r[i] * A[i][j]
    // q[i] = sum_j A[i][j] * p[j]
    //
    // With our layout:
    //   A[i][j] -> A_param(j, i)
    //   s(j)    -> s[j]
    //   q(i)    -> q[i]
    Func s_func("s"), q_func("q");

    // Pure definitions: initialize to zero
    s_func(j) = cast<num_t>(0);
    q_func(i) = cast<num_t>(0);

    // Reductions:
    // s[j] = sum_{i=0..n-1} r[i] * A[i][j]
    {
        RDom ri(0, n, "ri");
        s_func(j) += r_param(ri) * A_param(j, ri);
        // Optional schedule to make outer loop over j and inner over ri.
        s_func.update().reorder(j, ri);
    }

    // q[i] = sum_{j=0..m-1} A[i][j] * p[j]
    {
        RDom rj(0, m, "rj");
        q_func(i) += A_param(rj, i) * p_param(rj);
        // Optional schedule: outer loop over i, inner over rj.
        q_func.update().reorder(i, rj);
    }

    // Compute both at root
    s_func.compute_root();
    q_func.compute_root();

    // JIT-compile the kernels
    s_func.compile_jit();
    q_func.compile_jit();

    // Time the kernel: both s and q computations
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (mainly to prevent dead-code elimination)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s[0..m-1]
        for (int idx = 0; idx < m; idx++) {
            std::cerr << s(idx) << '\n';
        }

        // Print q[0..n-1]
        for (int idx = 0; idx < n; idx++) {
            std::cerr << q(idx) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
