// Include common PolyBench-style definitions (DATA_TYPE, N, M, etc.)
#include "defines.hpp"
// Include benchmark-specific definitions (declares N, M for bicg)
#include "bicg.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the arrays A (n x m), r (length n), and p (length m)
 * using a Halide pipeline that mirrors the original C init_array.
 *
 * Original C:
 *   for (i = 0; i < m; i++)
 *     p[i] = (DATA_TYPE)(i % m) / m;
 *   for (i = 0; i < n; i++) {
 *     r[i] = (DATA_TYPE)(i % n) / n;
 *     for (j = 0; j < m; j++)
 *       A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
 *   }
 *
 * Mapping to Halide:
 *   - C array A[N][M] (A[i][j]) is stored as Buffer A(j, i) with shape (M, N).
 *   - p[i]  -> Buffer p(i) of length m.
 *   - r[i]  -> Buffer r(i) of length n.
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,  // shape: (m, n) => A(j, i)
                       Halide::Buffer<num_t, 1> r,  // length: n
                       Halide::Buffer<num_t, 1> p)  // length: m
{
    Var i("i"), j("j");

    Func init_p("init_p"), init_r("init_r"), init_A("init_A");

    // p[i] = (i % m) / m;
    init_p(i) = cast<num_t>(i % m) / cast<num_t>(m);

    // r[i] = (i % n) / n;
    init_r(i) = cast<num_t>(i % n) / cast<num_t>(n);

    // A[i][j] = (i * (j + 1) % n) / n;
    // Remember: A is stored as A(j, i) in Halide.
    init_A(j, i) = cast<num_t>((i * (j + 1)) % n) / cast<num_t>(n);

    // Realize into the provided Buffers.
    init_p.realize(p);
    init_r.realize(r);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (as in PolyBench bicg.h)
    int n = N;  // number of rows
    int m = M;  // number of columns

    // Buffers corresponding to:
    //   A: N x M  -> Buffer(m, n), accessed as A(j, i)
    //   s: length M
    //   q: length N
    //   p: length M
    //   r: length N
    Halide::Buffer<num_t, 2> A(m, n);
    Halide::Buffer<num_t, 1> s(m);
    Halide::Buffer<num_t, 1> q(n);
    Halide::Buffer<num_t, 1> p(m);
    Halide::Buffer<num_t, 1> r(n);

    // ImageParams for the inputs to the Halide kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam p_param(type_of<num_t>(), 1, "p_param");
    ImageParam r_param(type_of<num_t>(), 1, "r_param");

    // Initialize the input data using a Halide-based initializer.
    init_array(m, n, A, r, p);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    p_param.set(p);
    r_param.set(r);

    // Vars for 1D outputs: s(j) for j in [0, m), q(i) for i in [0, n).
    Var i("i"), j("j");

    // Reductions:
    // Original C kernel:
    //
    //   for (i = 0; i < m; i++)
    //     s[i] = 0;
    //   for (i = 0; i < n; i++) {
    //     q[i] = 0;
    //     for (j = 0; j < m; j++) {
    //       s[j] = s[j] + r[i] * A[i][j];
    //       q[i] = q[i] + A[i][j] * p[j];
    //     }
    //   }
    //
    // Mathematically:
    //   s[j] = sum_{i=0..n-1} r[i] * A[i][j]
    //   q[i] = sum_{j=0..m-1} A[i][j] * p[j]
    //
    // We express these as two separate reductions.

    // RDom over rows (0 .. n-1)
    RDom ri(0, A.dim(1).extent(), "ri");  // matches i in A(i,j) => A_param(j, ri)

    // RDom over columns (0 .. m-1)
    RDom rj(0, A.dim(0).extent(), "rj");  // matches j in A(i,j) => A_param(rj, i)

    Func s_func("s"), q_func("q");

    // s[j] = sum_i r[i] * A[i][j]
    s_func(j) = cast<num_t>(0);
    s_func(j) += r_param(ri) * A_param(j, ri);

    // q[i] = sum_j A[i][j] * p[j]
    q_func(i) = cast<num_t>(0);
    q_func(i) += A_param(rj, i) * p_param(rj);

    // A straightforward schedule that mirrors the C loop structure:
    // - s: outer loop over j, inner reduction over i
    // - q: outer loop over i, inner reduction over j
    //
    // This is already the default, so we don't need extra scheduling
    // directives; we keep it simple and clear.
    s_func.compute_root();
    q_func.compute_root();

    // JIT-compile once before timing to exclude compilation time from measurement.
    s_func.compile_jit();
    q_func.compile_jit();

    // Measure execution time: run both reductions once.
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the results to stderr (like the GEMM example).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m)
        for (int idx = 0; idx < m; idx++) {
            std::cerr << s(idx) << '\n';
        }

        // Print q (length n)
        for (int idx = 0; idx < n; idx++) {
            std::cerr << q(idx) << '\n';
        }
    }

    // Print timing to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

