    //   A[N][M] with A[i][j], i in [0..n), j in [0..m)
    // Halide layout:
    //   A has shape (m, n), and A(j, i) corresponds to C's A[i][j].
    Halide::Buffer<num_t, 2> A(m, n);
    Halide::Buffer<num_t, 1> s(m);
    Halide::Buffer<num_t, 1> q(n);
    Halide::Buffer<num_t, 1> p(m);
    Halide::Buffer<num_t, 1> r(n);

    // ImageParams for the inputs to the Halide kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam p_param(type_of<num_t>(), 1, "p_param");
    ImageParam r_param(type_of<num_t>(), 1, "r_param");

    // Initialize data.
    init_array(m, n, A, r, p);

    // Bind buffers to ImageParams.
    A_param.set(A);
    p_param.set(p);
    r_param.set(r);

    // Declare Vars and RDom for the bicg kernel.
    Var i("i"), j("j");

    // The original C kernel:
    //
    // for (i = 0; i < M; i++)
    //   s[i] = 0;
    // for (i = 0; i < N; i++) {
    //   q[i] = 0;
    //   for (j = 0; j < M; j++) {
    //     s[j] += r[i] * A[i][j];
    //     q[i] += A[i][j] * p[j];
    //   }
    // }
    //
    // This computes:
    //   s[j] = sum_i r[i] * A[i][j]  (A^T * r)
    //   q[i] = sum_j A[i][j] * p[j]  (A * p)

    // Halide translation:
    // q(i) = sum_j A(i,j) * p(j)
    // s(j) = sum_i r(i)   * A(i,j)

    RDom ri(0, n, "ri"); // reduction over rows i in [0..n)
    RDom rj(0, m, "rj"); // reduction over cols j in [0..m)

    Func s_func("s_func"), q_func("q_func");

    // s[j] = sum_i r[i] * A[i][j]
    // A_param(j, ri) corresponds to C's A[ri][j]
    s_func(j) = cast<num_t>(0);
    s_func(j) += r_param(ri) * A_param(j, ri);

    // q[i] = sum_j A[i][j] * p[j]
    // A_param(rj, i) corresponds to C's A[i][rj]
    q_func(i) = cast<num_t>(0);
    q_func(i) += A_param(rj, i) * p_param(rj);

    // Optional simple schedules to reflect the original loop structure:
    // q: outer over i, inner over j (rj)
    q_func.compute_root();
    q_func.update().reorder(rj, i);

    // s: outer over j, inner over i (ri)
    s_func.compute_root();
    s_func.update().reorder(ri, j);

    // Build a pipeline that produces both s and q.
    Pipeline bicg_pipeline({s_func, q_func});

    // JIT-compile the pipeline.
    bicg_pipeline.compile_jit();

    // Time the kernel execution.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize s and q into the pre-allocated buffers.
    bicg_pipeline.realize({s, q});

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (similar spirit to Polybench's print_array).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m)
        for (int idx = 0; idx < m; idx++) {
            std::cerr << s(idx) << '\n';
        }

        // Print q (length n)
        for (int idx = 0; idx < n; idx++) {
            std::cerr << q(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout with 6 decimal places.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
